  function shape(label, group, key, w, h) {
    const src = art[key];
    return {label, group, preview: src, saveAs: null, parts: [{kind: 'image', text: label, src, w, h}]};
  }

  const inks = {
    teal: '#195654', gold: '#754513', plum: '#733c61',
    blue: '#31557d', violet: '#63427c', red: '#853c2c'
  };

  function webCard(label, group, key, tone, title, caption, linked) {
    const preview = art[key];
    const titleInk = inks[tone];
    const card = (w, h, fill) => ({kind: 'box', w, h, fill});
    const glyph = (dx, dy, size) => ({kind: 'image', src: preview, text: '', dx, dy, w: size, h: size});
    const heading = (dx, dy, w, h, fill, color, align = 'left') => ({
      kind: 'text', text: title, font_family: 'Verdana', font_size: 11,
      bold: true, dx, dy, w, h, fill, color, align
    });
    const detail = (dx, dy, w, h, color) => ({
      kind: linked ? 'link' : 'text', href: linked ? 'page:home' : '', text: caption,
      font_family: 'Verdana', font_size: 11, dx, dy, w, h, color
    });
    let parts;
    if (group === 'Badges') {
      parts = [card(170, 84, titleInk), heading(2, 2, 166, 19, '#eee4cd', titleInk, 'center'),
        glyph(6, 26, 42), detail(52, 31, 114, 50, '#fff4ca')];
    } else if (group === 'Navigation') {
      parts = [card(220, 34, '#d8d6c4'), glyph(2, 2, 30),
        heading(36, 2, 180, 13, '#d8d6c4', titleInk), detail(36, 15, 180, 17, '#16386e')];
    } else if (group === 'Media') {
      parts = [card(212, 58, '#202731'), glyph(5, 6, 44),
        heading(54, 5, 153, 18, titleInk, '#ffffff'), detail(56, 26, 150, 28, '#e0eeb8')];
    } else {
      parts = [card(220, 48, '#e8e2ce'), glyph(4, 7, 34),
        heading(42, 3, 175, 19, titleInk, '#ffffff'),
        detail(43, 24, 174, 22, linked ? '#1d326d' : '#292622')];
    }
    return {label, group, preview, saveAs: null, parts};
  }

  function board(label, group, key, saveAs, text) {
    const linked = saveAs === 'bbs-menu';
    const part = {
      kind: linked ? 'link' : 'text', href: linked ? 'page:home' : '', text,
      w: 290, h: text.split('\n').length * 20 + 12, font_family: 'Courier New',
      font_size: 14, fill: '#14251c', color: '#b8f895'
    };
    return {label, group, preview: art[key], saveAs, parts: [part]};
  }

